; ---------------------------------------------------------------
; void __near__ load_room (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_load_room: near

.segment	"CODE"

;
; ppu_off();
;
	jsr     _ppu_off
;
; vram_adr(NAMETABLE_A);
;
	ldx     #$20
	lda     #$00
	jsr     _vram_adr
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
	lda     #$00
	sta     _largeindex
	sta     _largeindex+1
L1942:	ldx     _largeindex+1
	cpx     #$04
	bcs     L1943
;
; if (game_mode == MODE_TITLE)
;
	lda     _game_mode
	bne     L2D55
;
; vram_put(title[largeindex]);
;
	lda     #<(_title)
	sta     ptr1
	lda     #>(_title)
	clc
	adc     _largeindex+1
	sta     ptr1+1
	ldy     _largeindex
;
; else if (game_mode == MODE_OPTIONS)
;
	jmp     L2D56
L2D55:	lda     _game_mode
	cmp     #$01
	bne     L1951
;
; vram_put(settings[largeindex]);
;
	lda     #<(_settings)
	sta     ptr1
	lda     #>(_settings)
	clc
	adc     _largeindex+1
	sta     ptr1+1
	ldy     _largeindex
;
; else
;
	jmp     L2D56
;
; vram_put(map_ptr[largeindex]);
;
L1951:	lda     _map_ptr
	clc
	adc     _largeindex
	sta     ptr1
	lda     _map_ptr+1
	adc     _largeindex+1
	sta     ptr1+1
	ldy     #$00
L2D56:	lda     (ptr1),y
	jsr     _vram_put
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
	inc     _largeindex
	bne     L1942
	inc     _largeindex+1
	jmp     L1942
;
; ppu_on_all();
;
L1943:	jmp     _ppu_on_all

.endproc

; ---------------------------------------------------------------
; void __near__ draw_sprites (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_draw_sprites: near

.segment	"CODE"

;
; oam_clear();
;
	jsr     _oam_clear
;
; if (bee_bump_timer > 0)
;
	lda     _bee_bump_timer
	beq     L2D5D
;
; oam_meta_spr(bee_bump_x, bee_bump_y, gamesprites_bump_data);
;
	jsr     decsp2
	lda     _bee_bump_x
	ldy     #$01
	sta     (sp),y
	lda     _bee_bump_y
	dey
